def smallest_divisor(a: list[int], threshold: int) -> int:
    def total(d: int) -> int:
        return sum((x + d - 1) // d for x in a)

    lo, hi = 1, max(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if total(mid) <= threshold:
            hi = mid
        else:
            lo = mid + 1
    return lo
